/**
 * AIService manages workspace AI settings, LLM providers, model registry,
 * unified MCP servers, autonomous agents, private streaming chat threads,
 * headless text/structured generation, and execution observability.
 */
/**
 * Retrieves workspace AI settings including model role defaults, governance, and current monthly spend.
 */
export async function getSettings(
  _req?: GetSettingsRequest
): Promise<Settings> {
  return request<Settings>({
    method: "GET",
    url: "/api/v1/platform/ai/settings",
  })
}

export function useGetSettingsQuery(
  req: GetSettingsRequest,
  options?: Omit<UseQueryOptions<Settings, Error>, "queryKey" | "queryFn">
) {
  return useQuery<Settings, Error>({
    queryKey: ["/api/v1/platform/ai/settings", req],
    queryFn: () => getSettings(req),
    ...options,
  })
}

/**
 * Updates workspace AI settings using a field mask.
 */
export async function updateSettings(
  req: UpdateSettingsRequest
): Promise<Settings> {
  const params = { ...req }
  delete (params as Record<string, unknown>).settings
  return request<Settings>({
    method: "PATCH",
    url: "/api/v1/platform/ai/settings",
    params: params,
    data: req.settings,
  })
}

export function useUpdateSettingsMutation(
  options?: UseMutationOptions<Settings, Error, UpdateSettingsRequest>
) {
  return useMutation<Settings, Error, UpdateSettingsRequest>({
    mutationFn: (req) => updateSettings(req),
    ...options,
  })
}

